RBinJavaAttrInfo *create_line_number_table_attr(ut8 *buffer, ut64 sz, ut64 buf_offset) {
	RBinJavaAttrInfo *attr = R_NEW0(RBinJavaAttrInfo);
	if (!attr) {
		return NULL;
	}

	// Read line number table length (u2)
	ut16 line_number_table_length = read16(buffer + buf_offset);
	buf_offset += 2;

	attr->line_number_table = R_NEWS0(RBinJavaLineNumberTable, line_number_table_length);
	if (!attr->line_number_table) {
		free(attr);
		return NULL;
	}

	for (ut16 i = 0; i < line_number_table_length; i++) {
		RBinJavaLineNumberTable *entry = &attr->line_number_table[i];

		if (buf_offset + 4 > sz) {
			// Buffer overflow
			free(attr->line_number_table);
			free(attr);
			return NULL;
		}

		// Read start_pc (u2)
		entry->start_pc = read16(buffer + buf_offset);
		buf_offset += 2;

		// Read line_number (u2)
		entry->line_number = read16(buffer + buf_offset);
		buf_offset += 2;
	}

	attr->size = line_number_table_length * 4 + 2;
	attr->type = R_BIN_JAVA_ATTR_LINE_NUMBER_TABLE;

	return attr;
}

