RBinJavaAttrInfo *r_bin_java_attr_info_line_number_table_new(ut8 *buffer, ut64 sz, ut64 buf_offset) {
    RBinJavaAttrInfo *attr = R_NEW0(RBinJavaAttrInfo);
    if (!attr) {
        return NULL;
    }

    attr->type = R_BIN_JAVA_ATTR_LINE_NUMBER_TABLE;
    attr->data = NULL;

    ut64 line_number_table_length = read_be16 (buffer + buf_offset);
    buf_offset += 2;

    attr->data = rz_list_new ();
    if (!attr->data) {
        free (attr);
        return NULL;
    }

    for (ut64 i = 0; i < line_number_table_length; i++) {
        RBinJavaLineNumberAttr *line_attr = R_NEW0 (RBinJavaLineNumberAttr);
        if (!line_attr) {
            rz_list_free (attr->data);
            free (attr);
            return NULL;
        }

        line_attr->start_pc = read_be16 (buffer + buf_offset);
        buf_offset += 2;
        line_attr->line_number = read_be16 (buffer + buf_offset);
        buf_offset += 2;

        rz_list_push (attr->data, line_attr);
    }

    attr->size = buf_offset - (buf_offset - sz);
    return attr;
