RBinJavaAttrInfo *r_bin_java_attr_info_new_line_number_table(ut8 *buffer, ut64 sz, ut64 buf_offset) {
	RBinJavaAttrInfo *attr = R_NEW0(RBinJavaAttrInfo);
	if (!attr) {
		return NULL;
	}

	RList *line_number_table = r_list_new();
	if (!line_number_table) {
		free(attr);
