RBinJavaAttrInfo *r_bin_java_attr_info_new_line_number_table(ut8 *buffer, ut64 sz, ut64 buf_offset) {
	RBinJavaAttrInfo *attr = NULL;
	ut64 line_number_table_length = 0;
	ut64 i = 0;

	if (!buffer || sz < buf_offset + 2) {
		return NULL;
	}

	attr = R_NEW0(RBinJavaAttrInfo);
	if (!attr) {
		return NULL;
	}

	attr->type = R_BIN_JAVA_ATTR_LINE_NUMBER_TABLE;
	attr->line_number_table = NULL;

	line_number_table_length = read16(buffer + buf_offset);
	attr->line_number_table_length = line_number_table_length;

	if (line_number_table_length > 0) {
		attr->line_number_table = R_NEWS(RBinJavaLineNumberTableEntry, line_number_table_length);
		if (!attr->line_number_table) {
			free(attr);
			return NULL;
		}

		for (i = 0; i < line_number_table_length; i++) {
			ut64 offset = buf_offset + 2 + (i * 4);
			if (sz < offset + 2) {
				r_list_free(attr->line_number_table);
				free(attr);
				return NULL;
			}
			attr->line_number_table[i].start_pc = read16(buffer + offset);
			attr->line_number_table[i].line_number = read16(buffer + offset + 2);
		}
	}

	attr->size = 2 + (line_number_table_length * 4);
	return attr;
}
